steps.command:
cat > /tmp/scan.py <<'E'
import ast,sys,glob
for f in sorted(glob.glob('billing/*.py')):
    src=open(f).read(); t=ast.parse(src); mod=f[8:-3]
    def walk(n,pre):
        for c in ast.iter_child_nodes(n):
            if isinstance(c,ast.ClassDef): walk(c,pre+[c.name])
            elif isinstance(c,(ast.FunctionDef,ast.AsyncFunctionDef)):
                print(f"{mod}.{'.'.join(pre+[c.name])} L{c.lineno} ret={ast.unparse(c.returns) if c.returns else None}")
                walk(c,pre+[c.name])
    walk(t,[])
E
.venv/bin/python -I /tmp/scan.py | wc -l; grep -n "Optional\|None" billing/*.py | grep -- "->"
